use std::collections::HashSet;

fn has_common_element(a: Vec<i32>, b: Vec<i32>) -> bool {
    if a.is_empty() || b.is_empty() {
        return false;
    }

    // Build a set from the smaller array for efficiency.
    if a.len() <= b.len() {
        let set: HashSet<i32> = a.into_iter().collect();
        b.into_iter().any(|x| set.contains(&x))
    } else {
        let set: HashSet<i32> = b.into_iter().collect();
        a.into_iter().any(|x| set.contains(&x))
    }
}